"""Declare project-management tools and schemas independently of scientific execution."""

from __future__ import annotations

from copy import deepcopy
import hashlib

from jsonschema import Draft202012Validator

from src.mcp.common.contracts import COMMON_PARAMETERS, RUN_DIAGNOSTICS_SCHEMA, HASH_SCHEMA, JOB_SCHEMA, LIMIT_SCHEMA, NATIVE_FILE_SCHEMA, NATIVE_SOURCE_SCHEMA, OFFSET_SCHEMA, REFERENCE_SCHEMA, RESPONSE_SCHEMA, UUID_SCHEMA, ServerContext, canonical_bytes
from src.srim.common.types import JSONObject


def build_catalog(context: ServerContext) -> JSONObject:
    """Return copied project tool/schema/example declarations for context.

    Validate static schemas without native execution, publishing cases, activating
    skills or populating reusable collections. Invalid schema raises ValueError.
    """
    text = {"type": "string"}
    nonblank = {"type": "string", "minLength": 1}
    positive = {"type": "integer", "minimum": 1}
    null = {"type": "null"}
    collection = {"enum": ["workflow", "analysis", "skill"]}
    version_reference = {"type": "object", "additionalProperties": False, "required": ["collection", "id", "version", "manifest_sha256"], "properties": {"collection": collection, "id": {"type": "string", "pattern": r"^[a-z0-9]+(?:-[a-z0-9]+)*$", "maxLength": 64}, "version": {"type": "string", "pattern": r"^v[1-9][0-9]*$"}, "manifest_sha256": HASH_SCHEMA}}
    analysis_reference = {"type": "object", "additionalProperties": False, "required": ["kind", "id", "revision", "sha256"], "properties": {"kind": {"const": "analysis"}, "id": {"type": "string", "pattern": r"^post_[0-9]{8}_[0-9]{6}_[1-9][0-9]*$"}, "revision": positive, "sha256": HASH_SCHEMA}}
    member_reference = {"oneOf": [analysis_reference, {"type": "object", "additionalProperties": False, "required": ["kind", "source"], "properties": {"kind": {"const": "native-source"}, "source": NATIVE_SOURCE_SCHEMA}}, {"type": "object", "additionalProperties": False, "required": ["kind", "server", "job_id", "request_sha256"], "properties": {"kind": {"const": "job"}, "server": {"const": "srim_mcp"}, "job_id": {"type": "string", "pattern": r"^job_[0-9a-f-]{36}$"}, "request_sha256": HASH_SCHEMA}}]}
    member = {"type": "object", "additionalProperties": False, "required": ["member_id", "role", "note", "reference"], "properties": {"member_id": UUID_SCHEMA, "role": {"type": "string", "minLength": 1, "maxLength": 128}, "note": text, "reference": member_reference}}
    case_spec = {"type": "object", "additionalProperties": False, "required": ["title", "question", "status", "tags", "notes", "members"], "properties": {"title": {"type": "string", "minLength": 1, "maxLength": 512}, "question": nonblank, "status": {"enum": ["open", "paused", "completed", "archived"]}, "tags": {"type": "array", "maxItems": 64, "uniqueItems": True, "items": {"type": "string", "minLength": 1, "maxLength": 128}}, "notes": text, "members": {"type": "array", "items": member}}}
    method = {"type": "object", "additionalProperties": False, "required": ["kind", "reference", "description", "citations", "code_artifacts"], "properties": {"kind": {"enum": ["ad-hoc", "registered"]}, "reference": {"oneOf": [null, {**version_reference, "properties": {**version_reference["properties"], "collection": {"const": "analysis"}}}]}, "description": nonblank, "citations": {"type": "array", "items": {"type": "object", "additionalProperties": False, "required": ["title", "locator"], "properties": {"title": nonblank, "locator": nonblank}}}, "code_artifacts": {"type": "array", "items": text}}}
    inputs = {"type": "array", "items": {"type": "object", "additionalProperties": False, "required": ["source", "files", "purpose"], "properties": {"source": NATIVE_SOURCE_SCHEMA, "files": {"type": "array", "minItems": 1, "items": NATIVE_FILE_SCHEMA}, "purpose": nonblank}}}
    eligibility = {"type": "object", "additionalProperties": False, "required": ["allow_failed_runs", "allow_checkpoint_recovery", "require_complete_parser"], "properties": {key: {"type": "boolean"} for key in ("allow_failed_runs", "allow_checkpoint_recovery", "require_complete_parser")}}
    analysis_spec = {"type": "object", "additionalProperties": False, "required": ["title", "question", "method", "inputs", "eligibility", "parameters", "findings", "limitations"], "properties": {"title": {"type": "string", "minLength": 1, "maxLength": 512}, "question": nonblank, "method": method, "inputs": inputs, "eligibility": eligibility, "parameters": {"type": "object", "description": "Explicit ad-hoc finite JSON parameters, or parameters validated by the selected registered method schema."}, "findings": text, "limitations": text}}
    file_spec = {"type": "object", "additionalProperties": False, "required": ["name", "role", "source_path", "media_type"], "properties": {"name": nonblank, "role": {"enum": ["method", "code", "data", "figure", "report", "diagnostic"]}, "source_path": nonblank, "media_type": nonblank}}
    file_inventory = {"type": "array", "items": {"type": "object", "additionalProperties": False, "required": ["path", "sha256", "size_bytes"], "properties": {"path": nonblank, "sha256": HASH_SCHEMA, "size_bytes": {"type": "integer", "minimum": 0}}}}
    proposed_manifest = {"type": "object", "additionalProperties": False, "required": ["schema_version", "collection", "id", "title", "description", "input_schema", "output_schema", "prerequisites", "procedure", "evidence", "limitations", "files"], "properties": {"schema_version": {"const": 1}, "collection": collection, "id": version_reference["properties"]["id"], "title": nonblank, "description": nonblank, "input_schema": {"type": "object", "description": "Closed Draft 2020-12 schema; internal references only."}, "output_schema": {"type": "object", "description": "Closed Draft 2020-12 schema; internal references only."}, "prerequisites": {"type": "array", "items": text}, "procedure": {"type": "array", "minItems": 1, "items": {"type": "object", "additionalProperties": False, "required": ["step_id", "instruction", "tool_names"], "properties": {"step_id": nonblank, "instruction": nonblank, "tool_names": {"type": "array", "items": text}}}}, "evidence": {"type": "array", "items": text}, "limitations": {"type": "array", "items": text}, "files": file_inventory}}
    candidate_spec = {"type": "object", "additionalProperties": False, "required": ["collection", "proposed_manifest", "rationale", "evidence_references"], "properties": {"collection": collection, "proposed_manifest": proposed_manifest, "rationale": nonblank, "evidence_references": {"type": "array", "items": REFERENCE_SCHEMA}}}
    measurement = {"type": "object", "additionalProperties": False, "required": ["criterion", "value", "unit", "method", "basis"], "properties": {"criterion": {"enum": ["time", "cost", "user_effort", "quality"]}, "value": {"type": "number"}, "unit": text, "method": text, "basis": {"enum": ["measured", "estimated"]}}}
    observation = {"type": "object", "additionalProperties": False, "required": ["problem", "evidence", "sources", "criteria", "measurements", "uncertainty"], "properties": {"problem": nonblank, "evidence": nonblank, "sources": {"type": "array", "items": text}, "criteria": {"type": "array", "items": {"enum": ["time", "cost", "user_effort", "quality"]}}, "measurements": {"type": "array", "items": measurement}, "uncertainty": text}}
    assessment = {'type': 'object', 'additionalProperties': False, 'required': ['observation_ids', 'disposition', 'rationale', 'uncertainty', 'follow_up', 'related_proposal_ids', 'predecessor_assessment_id'], 'properties': {'observation_ids': {'type': 'array', 'minItems': 1, 'uniqueItems': True, 'items': {'type': 'string', 'pattern': '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'}}, 'disposition': {'enum': ['proposal_needed', 'deferred_insufficient_evidence', 'already_addressed', 'no_reusable_change']}, 'rationale': {'type': 'string', 'pattern': '\\S'}, 'uncertainty': {'type': 'string'}, 'follow_up': {'type': 'string'}, 'related_proposal_ids': {'type': 'array', 'uniqueItems': True, 'items': {'type': 'string', 'pattern': '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'}}, 'predecessor_assessment_id': {'oneOf': [{'type': 'string', 'pattern': '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'}, {'type': 'null'}]}}, 'allOf': [{'if': {'properties': {'disposition': {'enum': ['proposal_needed', 'deferred_insufficient_evidence']}}}, 'then': {'properties': {'follow_up': {'type': 'string', 'pattern': '\\S'}}}}, {'if': {'properties': {'disposition': {'const': 'already_addressed'}}}, 'then': {'properties': {'related_proposal_ids': {'minItems': 1}}}, 'else': {'properties': {'related_proposal_ids': {'maxItems': 0}}}}]}
    failure = {"oneOf": [null, {"type": "object", "additionalProperties": False, "required": ["code", "message"], "properties": {"code": nonblank, "message": nonblank}}]}
    revision = {"oneOf": [positive, null], "default": None}
    nullable_id = {"type": ["string", "null"], "default": None}
    params = deepcopy(COMMON_PARAMETERS)
    params.update({
        "cases_list": {"status": {"enum": [None, "open", "paused", "completed", "archived"], "default": None}, "offset": OFFSET_SCHEMA, "limit": LIMIT_SCHEMA},
        "case_get": {"case_id": nonblank, "revision": revision}, "case_create": {"spec": case_spec, "allocated_id": nullable_id}, "case_revise": {"case_id": nonblank, "expected_revision": positive, "spec": case_spec},
        "runs_list": {"engine": {"enum": [None, "sr", "trim", "sr-capture"], "default": None}, "status": {"enum": [None, "created", "running", "succeeded", "failed"], "default": None}, "offset": OFFSET_SCHEMA, "limit": LIMIT_SCHEMA},
        "run_get": {"simulation_id": nonblank}, "run_source": {"simulation_id": nonblank}, "physics_job_get": {"job_id": {"type": "string", "pattern": r"^job_[0-9a-f-]{36}$"}},
        "analyses_list": {"status": {"enum": [None, "draft", "completed", "failed"], "default": None}, "offset": OFFSET_SCHEMA, "limit": LIMIT_SCHEMA}, "analysis_get": {"analysis_id": nonblank, "revision": revision},
        "analysis_create": {"spec": analysis_spec, "allocated_id": nullable_id}, "analysis_revise": {"analysis_id": nonblank, "expected_revision": positive, "spec": analysis_spec}, "analysis_attach": {"analysis_id": nonblank, "expected_revision": positive, "files": {"type": "array", "minItems": 1, "items": file_spec}},
        "analysis_finish": {"analysis_id": nonblank, "expected_revision": positive, "status": {"enum": ["completed", "failed"]}, "findings": text, "limitations": text, "failure": failure},
        "collections_list": {}, "collection_entries": {"collection": collection, "offset": OFFSET_SCHEMA, "limit": LIMIT_SCHEMA}, "collection_entry_get": {"reference": version_reference},
        "candidates_list": {"collection": {"enum": [None, "workflow", "analysis", "skill"], "default": None}, "offset": OFFSET_SCHEMA, "limit": LIMIT_SCHEMA}, "candidate_get": {"candidate_id": nonblank}, "candidate_create": {"spec": candidate_spec, "files": {"type": "array", "items": file_spec}},
        "repository_skills_list": {}, "improvement_status": {"proposal_id": {"oneOf": [UUID_SCHEMA, null], "default": None}}, "improvement_observe": {"details": observation}, "improvement_assess": {"details": assessment}, "improvement_proposal_create": {"proposal_id": UUID_SCHEMA, "observation_ids": {"type": "array", "minItems": 1, "uniqueItems": True, "items": UUID_SCHEMA}, "markdown": nonblank},
    })
    mutations = {"case_create", "case_revise", "analysis_create", "analysis_revise", "analysis_attach", "analysis_finish", "candidate_create", "improvement_observe", "improvement_assess", "improvement_proposal_create"}
    tools, capabilities = {}, {}
    descriptions = {"run_get": "Read run metadata, input verification and structured diagnostics. Investigate failures before exclusion; report independent findings and unresolved causes.", "case_create": "Create one case per user-defined scientific objective, including several within one query. Honor explicit case count or separation before case-specific work; shared paths or evidence do not merge cases. Share evidence by reference. No implicit current case or native execution.", "case_revise": "Append a full case revision using explicit case_id and expected_revision. Track its scientific objective and status independently; shared workflow paths or run/analysis references do not merge cases.", "analysis_create": "Record an analysis method/input plan; no scientific method executes.", "analysis_finish": "Seal findings/artifact provenance after verification; completion does not certify scientific correctness.", "candidate_create": "Preserve an unapproved reusable workflow/analysis/skill candidate; never promote or execute it.", "improvement_observe": "Preserve meaningful improvement evidence without generating approvals or starting trials.", "improvement_assess": "Preserve an evidence assessment and follow-up disposition; never approve, implement or activate changes.", "improvement_proposal_create": "Preserve exact proposal Markdown and linked evidence; human approval and trial/adoption remain external.", "physics_job_get": "Read a changing srim_mcp on-disk job snapshot; cannot launch, cancel, retry or edit that job."}
    for name, properties in params.items():
        properties = deepcopy(properties)
        if name in mutations:
            properties["request_id"] = UUID_SCHEMA
        family = "discovery" if name in COMMON_PARAMETERS else "cases" if name.startswith("case") else "analysis" if name.startswith("analys") else "results" if name.startswith(("run", "physics")) else "improvement" if name.startswith("improvement") else "reuse"
        description = descriptions.get(name, name.replace("_", " ").capitalize() + "; validate provenance and use explicit immutable references.")
        schema = {"type": "object", "additionalProperties": False, "required": [key for key, value in properties.items() if "default" not in value], "properties": properties}
        tools[name] = {"name": name, "family": family, "description": description, "mutating": name in mutations, "inputSchema": schema, "outputSchema": RESPONSE_SCHEMA}
        identity = "capability_" + name.replace("_", "-")
        capabilities[identity] = {"id": identity, "title": name.replace("_", " ").capitalize(), "family": family, "summary": description, "tool_names": [name], "implementation": "implemented", "exposure": "mcp", "input_schema_ids": ["tool." + name], "output_schema_ids": ["mcp.response.v1"], "parameters": [{"pointer": "/" + key, "description": key.replace("_", " "), "value_type": value.get("type", "union"), "unit": None, "required": key in schema["required"], "default": value.get("default"), "enum": value.get("enum"), "minimum": value.get("minimum"), "maximum": value.get("maximum"), "bounds_kind": "schema", "reason": "Explicit record/reference validation", "source": "doc/guides/project-management.md"} for key, value in properties.items()], "units": {}, "defaults": {key: value["default"] for key, value in properties.items() if "default" in value}, "effects": ["Durable revision/publication job"] if name in mutations else ["Verified read; no scientific execution"], "compatibility": {"workspace": "local Windows project", "sessions": "multiple explicit case IDs; no session-wide current case"}, "automation": "No native execution, automatic adoption or arbitrary code interpreter", "availability": "Reusable active collections start empty", "evidence": [{"claim": "Provenance/approval boundaries follow the accepted project contract", "kind": "source", "reference": "doc/guides/project-management.md", "scope": "Organizational records, not independent scientific validation"}], "limitations": ["Case status is an organizational label", "Analysis completion verifies provenance, not physics", "Self-improvement remains instruction-based with explicit human trial/adoption approval"], "example_ids": [], "python_apis": ["src.case.records", "src.analysis.records", "src.plan.catalog", "src.plan.improvement"]}
    schemas = {"project.case-spec.v1": case_spec, "project.analysis-spec.v1": analysis_spec, "project.candidate-spec.v1": candidate_spec, "project.observation.v1": observation, "project.assessment.v2": assessment, "mcp.run-diagnostics.v1": RUN_DIAGNOSTICS_SCHEMA, "mcp.response.v1": RESPONSE_SCHEMA, "mcp.reference.v1": REFERENCE_SCHEMA, "mcp.job.v1": JOB_SCHEMA, "native.source.v1": NATIVE_SOURCE_SCHEMA, "native.file.v1": NATIVE_FILE_SCHEMA, **{"tool." + name: tool["inputSchema"] for name, tool in tools.items()}}
    revision_header = {"schema_version": {"const": 1}, "kind": {"enum": ["case", "analysis"]}, "id": nonblank, "revision": positive, "previous_sha256": {"oneOf": [HASH_SCHEMA, null]}, "request_id": UUID_SCHEMA, "created_at": nonblank, "updated_at": nonblank}
    schemas["project.case.v1"] = {"type": "object", "additionalProperties": False, "required": list(revision_header) + case_spec["required"], "properties": {**revision_header, **case_spec["properties"], "kind": {"const": "case"}}}
    stored_artifact = {"type": "object", "additionalProperties": False, "required": ["name", "role", "path", "sha256", "size_bytes", "media_type", "source"], "properties": {"name": nonblank, "role": file_spec["properties"]["role"], "path": nonblank, "sha256": HASH_SCHEMA, "size_bytes": {"type": "integer", "minimum": 0}, "media_type": text, "source": nonblank}}
    schemas["project.analysis.v1"] = {"type": "object", "additionalProperties": False, "required": list(revision_header) + analysis_spec["required"] + ["status", "artifacts", "failure"], "properties": {**revision_header, **analysis_spec["properties"], "kind": {"const": "analysis"}, "status": {"enum": ["draft", "completed", "failed"]}, "artifacts": {"type": "array", "items": stored_artifact}, "failure": failure}}
    examples = {}
    for index, (title, question) in enumerate((("Stopping study", "Compare stopping across selected energies"), ("Range trend study", "How does projected range change across the selected energies?")), 1):
        identifier = "case-create-" + str(index)
        examples[identifier] = {"id": identifier, "tool": "case_create", "arguments": {"request_id": f"00000000-0000-0000-0000-{index:012d}", "spec": {"title": title, "question": question, "status": "open", "tags": [], "notes": "", "members": []}}, "purpose": "Create one of two user-defined scientific objectives in one query; eligible native evidence may be shared", "prerequisites": ["Identify the user-defined objectives and honor any requested count or separation before case-specific work; two is only an example"], "expected": "Job reference, followed by independent immutable case reference", "limitations": ["Keep returned case IDs and revisions explicit; no automatic current case"]}
    examples["analysis-ad-hoc"] = {"id": "analysis-ad-hoc", "tool": "analysis_create", "arguments": {"request_id": "00000000-0000-0000-0000-000000000003", "spec": {"title": "Evidence inspection", "question": "What does the selected evidence establish?", "method": {"kind": "ad-hoc", "reference": None, "description": "Document the explicitly chosen inspection method and attach reproducible evidence", "citations": [], "code_artifacts": []}, "inputs": [], "eligibility": {"allow_failed_runs": False, "allow_checkpoint_recovery": False, "require_complete_parser": True}, "parameters": {}, "findings": "", "limitations": ""}}, "purpose": "Record an explicit method plan", "prerequisites": ["Choose eligible pinned input files before scientific analysis"], "expected": "Draft analysis reference", "limitations": ["No computation or scientific conclusion is inferred"]}
    for identity, example in examples.items():
        Draft202012Validator(tools[example["tool"]]["inputSchema"]).validate(example["arguments"])
        capabilities["capability_" + example["tool"].replace("_", "-")]["example_ids"].append(identity)
    for schema in schemas.values():
        Draft202012Validator.check_schema(schema)
    result = {"server": context.name, "tools": tools, "schemas": schemas, "capabilities": capabilities, "examples": examples, "limits": deepcopy(context.limits), "instructions": "Use one MCP case per user-defined scientific objective. A single query may contain several cases. Honor any explicitly requested case count or separation before starting case-specific work. Shared workflow paths or evidence do not merge cases. Track each case independently and share workflow steps, native evidence and analyses through explicit references where appropriate. Use explicit case IDs/revisions and map each objective to its case before proceeding. Reuse matching existing cases; clarify ambiguous boundaries. If existing records combine explicitly separated objectives, report the mismatch and propose a correction without waiting for cleanup. MCP does not infer objectives from query text. Review run_get diagnostics before excluding failed runs; distinguish recorded findings from unresolved causes. Coordinate native execution through srim_mcp. Record methods and pinned evidence without treating provenance completion as scientific validation. Reusable collections start empty; no MCP tool can approve/promote a candidate or start/adopt a self-improvement trial."}
    result["generation"] = hashlib.sha256(canonical_bytes(result)).hexdigest()
    return deepcopy(result)
